package dev.nanites.forge;

import com.google.gson.*;
import dev.nanites.core.MachineTools;
import dev.nanites.game.*;
import net.minecraft.core.*;
import net.minecraft.core.registries.Registries;
import net.minecraft.resources.*;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.*;
import net.minecraft.nbt.*;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.block.state.*;
import net.minecraft.world.level.block.state.properties.Property;
import net.minecraft.world.level.saveddata.SavedData;
import net.minecraftforge.common.capabilities.*;
import net.minecraftforge.items.*;
import net.minecraftforge.items.wrapper.PlayerMainInvWrapper;
import net.minecraftforge.energy.IEnergyStorage;
import net.minecraftforge.fluids.FluidStack;
import net.minecraftforge.fluids.capability.IFluidHandler;
import net.minecraftforge.registries.ForgeRegistries;
import java.util.*;

/** Real Forge capability boundary; all resolution/simulation/mutation stays on the server thread. */
public final class ForgeMachines {
    private ForgeMachines() {}
    private static final List<String> SIDES=List.of("none","down","up","north","south","west","east");
    private record Target(JsonObject json,ServerLevel level,BlockPos pos,boolean player,String side) {}
    private record Face<T>(String side,T handler) {}
    private static void thread(MinecraftServer s){if(!s.isSameThread())throw new IllegalStateException("Machine access requires server thread");}
    private static ServerPlayer player(MinecraftServer s,UUID id){var p=s.getPlayerList().getPlayer(id);if(p==null||!p.isAlive())throw new IllegalStateException("Owner offline/dead");return p;}
    private static Target target(MinecraftServer s,UUID id,JsonObject j){
        thread(s);var p=player(s,id);String type=j.get("type").getAsString(),side=j.get("side").getAsString();if(!side.equals("auto")&&!SIDES.contains(side))throw new IllegalArgumentException("side auto|none|down|up|north|south|west|east");
        if(!Set.of("block","player").contains(type))throw new IllegalArgumentException("target.type block|player (owner)");
        String d=j.get("dimension").getAsString();ResourceLocation loc=ResourceLocation.tryParse(d.isEmpty()?p.level().dimension().location().toString():d);if(loc==null)throw new IllegalArgumentException("Invalid dimension");var level=s.getLevel(ResourceKey.create(Registries.DIMENSION,loc));if(level==null)throw new MachineAdapters.WaitingChunk("Dimension unavailable: "+loc);
        BlockPos pos=new BlockPos(j.get("x").getAsInt(),j.get("y").getAsInt(),j.get("z").getAsInt());
        if(type.equals("player"))return new Target(j,p.serverLevel(),p.blockPosition(),true,side);
        if(pos.getY()<level.getMinBuildHeight()||pos.getY()>=level.getMaxBuildHeight()||!level.getWorldBorder().isWithinBounds(pos))throw new IllegalArgumentException("Outside build height/world border");
        if(!level.hasChunkAt(pos))throw new MachineAdapters.WaitingChunk("WAITING_CHUNK "+loc+" "+pos.toShortString()+"; no force-load");return new Target(j,level,pos,false,side);
    }
    private static <T> List<Face<T>> faces(MinecraftServer s,UUID id,Target t,Capability<T> cap){
        var out=new ArrayList<Face<T>>();if(t.player){if(cap==ForgeCapabilities.ITEM_HANDLER){@SuppressWarnings("unchecked")T inventory=(T)new PlayerMainInvWrapper(player(s,id).getInventory());out.add(new Face<>("player",inventory));}return out;}
        var be=t.level.getBlockEntity(t.pos);if(be==null)return out;
        for(String side:t.side.equals("auto")?SIDES:List.of(t.side)){Direction dir=side.equals("none")?null:Direction.byName(side);be.getCapability(cap,dir).resolve().ifPresent(h->out.add(new Face<>(side,h)));}return out;
    }
    private static JsonObject item(ItemStack stack){var j=new JsonObject();j.addProperty("id",stack.isEmpty()?"minecraft:air":Objects.toString(ForgeRegistries.ITEMS.getKey(stack.getItem())));j.addProperty("amount",stack.getCount());if(stack.hasTag())nbt(j,stack.getTag());return j;}
    private static void nbt(JsonObject j,CompoundTag tag){String text=tag.toString();j.addProperty("nbt",text.substring(0,Math.min(96,text.length())));j.addProperty("nbt_truncated",text.length()>96);}
    private static JsonObject fluid(FluidStack stack){var j=new JsonObject();j.addProperty("id",Objects.toString(ForgeRegistries.FLUIDS.getKey(stack.getFluid())));j.addProperty("amount",stack.getAmount());if(stack.hasTag())nbt(j,stack.getTag());return j;}
    private static <T extends Comparable<T>> String value(BlockState state,Property<T> p){return p.getName(state.getValue(p));}
    private static JsonObject state(Target t){var j=new JsonObject();if(t.player)return j;var state=t.level.getBlockState(t.pos);j.addProperty("blockstate",ForgeConstruction.describe(state));var properties=new JsonObject();for(var p:state.getProperties()){var x=new JsonObject();x.addProperty("value",value(state,p));var legal=new JsonArray();for(var v:p.getPossibleValues())legal.add(v.toString());x.add("legal",legal);properties.add(p.getName(),x);}j.add("properties",properties);j.addProperty("redstone_signal",t.level.getBestNeighborSignal(t.pos));return j;}
    private static JsonObject inspect(MinecraftServer s,UUID id,JsonObject args){
        var t=target(s,id,args.getAsJsonObject("target"));int offset=args.get("offset").getAsInt(),limit=Math.min(args.get("limit").getAsInt(),t.side.equals("auto")?2:16);var out=state(t);out.addProperty("effective_limit",limit);out.addProperty("offset",offset);out.add("target",t.json.deepCopy());out.addProperty("status","OBSERVED_SERVER_MAIN");var sided=new JsonArray();
        for(String side:t.player?List.of("none"):t.side.equals("auto")?SIDES:List.of(t.side)){Target one=new Target(t.json,t.level,t.pos,t.player,side);var x=new JsonObject();x.addProperty("side",side);
            var items=faces(s,id,one,ForgeCapabilities.ITEM_HANDLER);if(!items.isEmpty()){var h=items.get(0).handler;var slots=new JsonArray();x.addProperty("slots",h.getSlots());for(int slot=offset;slot<Math.min(h.getSlots(),offset+limit);slot++){var st=h.getStackInSlot(slot).copy();var row=item(st);row.addProperty("slot",slot);row.addProperty("limit",h.getSlotLimit(slot));row.addProperty("extract_simulated",h.extractItem(slot,Math.max(1,st.getCount()),true).getCount());slots.add(row);}x.add("inventory",slots);}
            var energy=faces(s,id,one,ForgeCapabilities.ENERGY);if(!energy.isEmpty()){var h=energy.get(0).handler;var e=new JsonObject();e.addProperty("stored",h.getEnergyStored());e.addProperty("capacity",h.getMaxEnergyStored());e.addProperty("can_extract",h.canExtract());e.addProperty("can_receive",h.canReceive());x.add("energy",e);}
            var fluids=faces(s,id,one,ForgeCapabilities.FLUID_HANDLER);if(!fluids.isEmpty()){var h=fluids.get(0).handler;x.addProperty("tank_count",h.getTanks());var tanks=new JsonArray();for(int tank=offset;tank<Math.min(h.getTanks(),offset+limit);tank++){var f=h.getFluidInTank(tank).copy();var row=fluid(f);row.addProperty("tank",tank);row.addProperty("capacity",h.getTankCapacity(tank));row.addProperty("valid_current",h.isFluidValid(tank,f));tanks.add(row);}x.add("tanks",tanks);}
            sided.add(x);
        }
        out.add("sides",sided);out.add("escrow",escrow(s).summary(id));return out;
    }
    private static JsonObject scan(MinecraftServer s,UUID id,JsonObject args){
        var t=target(s,id,args.getAsJsonObject("target"));if(t.player)throw new IllegalArgumentException("Scan center must be block");int radius=args.get("radius").getAsInt(),offset=args.get("offset").getAsInt(),limit=args.get("limit").getAsInt(),width=radius*2+1,total=width*width*width;var hits=new JsonArray();int unloaded=0,end=Math.min(total,offset+limit);
        for(int index=offset;index<end;index++){BlockPos pos=t.pos.offset(index%width-radius,(index/width)%width-radius,index/(width*width)-radius);if(pos.getY()<t.level.getMinBuildHeight()||pos.getY()>=t.level.getMaxBuildHeight())continue;if(!t.level.hasChunkAt(pos)){unloaded++;continue;}var j=t.json.deepCopy();j.addProperty("x",pos.getX());j.addProperty("y",pos.getY());j.addProperty("z",pos.getZ());var one=new Target(j,t.level,pos,false,"auto");var supported=new JsonArray();for(String side:SIDES){var face=new Target(j,t.level,pos,false,side);var c=new JsonObject();c.addProperty("side",side);c.addProperty("items",!faces(s,id,face,ForgeCapabilities.ITEM_HANDLER).isEmpty());c.addProperty("energy",!faces(s,id,face,ForgeCapabilities.ENERGY).isEmpty());c.addProperty("fluid",!faces(s,id,face,ForgeCapabilities.FLUID_HANDLER).isEmpty());if(c.get("items").getAsBoolean()||c.get("energy").getAsBoolean()||c.get("fluid").getAsBoolean())supported.add(c);}if(!supported.isEmpty()){var hit=new JsonObject();hit.addProperty("index",index);hit.add("target",j);hit.addProperty("blockstate",ForgeConstruction.describe(t.level.getBlockState(pos)));hit.add("sides",supported);hits.add(hit);if(hits.size()>=8){end=index+1;break;}}}
        var out=new JsonObject();out.add("machines",hits);out.addProperty("offset",offset);out.addProperty("next_offset",end);out.addProperty("total_cells",total);out.addProperty("complete",end>=total);out.addProperty("unloaded_cells",unloaded);out.addProperty("status",unloaded>0?"PARTIAL_UNLOADED":"OBSERVED_SERVER_MAIN");return out;
    }
    private static List<Integer> slots(int count,int slot){if(slot>=count)throw new IllegalArgumentException("Slot/tank outside capability");if(slot>=0)return List.of(slot);var out=new ArrayList<Integer>();for(int i=0;i<Math.min(256,count);i++)out.add(i);return out;}
    private static int insert(IItemHandler h,int slot,ItemStack item,boolean simulate){int remaining=item.getCount();for(int i:slots(h.getSlots(),slot)){var copy=item.copy();copy.setCount(remaining);remaining=h.insertItem(i,copy,simulate).getCount();if(remaining==0)break;}return item.getCount()-remaining;}
    private static ItemStack sized(ItemStack sample,int amount){var copy=sample.copy();copy.setCount(amount);return copy;}
    private static FluidStack sized(FluidStack sample,int amount){var copy=sample.copy();copy.setAmount(amount);return copy;}
    private static JsonObject receipt(CapabilityTransfer.Result result,String from,String to,JsonObject identity,boolean preview){var o=new JsonObject();o.addProperty("status",preview?"SIMULATED":result.held()>0?"PARTIAL_ESCROW":"EXECUTED_SERVER_MAIN");o.addProperty("simulated",result.simulated());o.addProperty("extracted",result.extracted());o.addProperty("moved",result.moved());o.addProperty("refunded",result.refunded());o.addProperty("held",result.held());o.addProperty("from_side",from);o.addProperty("to_side",to);o.add("resource",identity);return o;}
    private static void distinct(Target from,Target to){if(from.player&&to.player||!from.player&&!to.player&&from.level==to.level&&from.pos.equals(to.pos))throw new IllegalArgumentException("Same endpoint transfer rejected (sided wrappers can alias)");}
    private static final class SearchBudget {int candidates;final long deadline=System.nanoTime()+2_000_000;boolean available(){return candidates++<256&&(candidates==1||System.nanoTime()<=deadline);}}
    private static JsonObject budgetReceipt(){var o=new JsonObject();o.addProperty("status","SEARCH_BUDGET_EXHAUSTED");o.addProperty("moved",0);o.addProperty("reason","Auto discovery simulation exceeded 256 candidates/2ms; inspect and choose explicit sides/source slot, or split into adapter steps. No extraction performed.");return o;}
    private static JsonObject transfer(MinecraftServer s,UUID id,String tool,JsonObject a){
        var from=target(s,id,a.getAsJsonObject("from"));var to=target(s,id,a.getAsJsonObject("to"));distinct(from,to);boolean preview=a.get("preview").getAsBoolean();int amount=a.get("amount").getAsInt();var saved=escrow(s);if(!preview&&saved.count(id)>=128)throw new IllegalStateException("Recover escrow first (128 entries)");var search=new SearchBudget();
        if(tool.equals("transfer_items")){
            for(var f:faces(s,id,from,ForgeCapabilities.ITEM_HANDLER))for(var t:faces(s,id,to,ForgeCapabilities.ITEM_HANDLER)){if(f.handler==t.handler)continue;for(int slot:slots(f.handler.getSlots(),a.get("from_slot").getAsInt())){if(!search.available())return budgetReceipt();ItemStack sample=f.handler.extractItem(slot,amount,true).copy();if(sample.isEmpty())continue;int dst=a.get("to_slot").getAsInt();
                CapabilityTransfer.Port source=new CapabilityTransfer.Port(){public int extract(int n,boolean sim){var actual=f.handler.extractItem(slot,n,sim);if(!actual.isEmpty()&&!ItemStack.isSameItemSameTags(sample,actual)){if(!sim)saved.hold(id,"items",actual.save(new CompoundTag()));throw new IllegalStateException("Capability changed resource between simulation/commit; retained actual in escrow");}return actual.getCount();}public int receive(int n,boolean sim){return insert(f.handler,slot,sized(sample,n),sim);}};
                CapabilityTransfer.Port dest=new CapabilityTransfer.Port(){public int extract(int n,boolean sim){return 0;}public int receive(int n,boolean sim){return insert(t.handler,dst,sized(sample,n),sim);}};
                var predicted=CapabilityTransfer.move(source,dest,amount,true,n->{});if(predicted.simulated()==0)continue;var result=preview?predicted:CapabilityTransfer.move(source,dest,amount,false,n->saved.hold(id,"items",sized(sample,n).save(new CompoundTag())));var out=receipt(result,f.side,t.side,item(sample),preview);out.addProperty("from_slot",slot);out.addProperty("to_slot",dst);return out;
            }}
        }else if(tool.equals("transfer_energy")){
            for(var f:faces(s,id,from,ForgeCapabilities.ENERGY))for(var t:faces(s,id,to,ForgeCapabilities.ENERGY)){if(f.handler==t.handler||!f.handler.canExtract()||!t.handler.canReceive())continue;if(!search.available())return budgetReceipt();CapabilityTransfer.Port source=energy(f.handler),dest=energy(t.handler);var predicted=CapabilityTransfer.move(source,dest,amount,true,n->{});if(predicted.simulated()==0)continue;int beforeFrom=f.handler.getEnergyStored(),beforeTo=t.handler.getEnergyStored();var result=preview?predicted:CapabilityTransfer.move(source,dest,amount,false,n->{var tag=new CompoundTag();tag.putInt("amount",n);saved.hold(id,"energy",tag);});var identity=new JsonObject();identity.addProperty("unit","FE");var out=receipt(result,f.side,t.side,identity,preview);out.addProperty("from_before",beforeFrom);out.addProperty("from_after",f.handler.getEnergyStored());out.addProperty("to_before",beforeTo);out.addProperty("to_after",t.handler.getEnergyStored());return out;}
        }else{
            for(var f:faces(s,id,from,ForgeCapabilities.FLUID_HANDLER))for(var t:faces(s,id,to,ForgeCapabilities.FLUID_HANDLER)){if(f.handler==t.handler)continue;for(int tank:slots(f.handler.getTanks(),a.get("from_slot").getAsInt())){if(!search.available())return budgetReceipt();FluidStack sample=f.handler.getFluidInTank(tank).copy();if(sample.isEmpty())continue;int dst=a.get("to_slot").getAsInt();if(dst>=0){slots(t.handler.getTanks(),dst);if(!t.handler.isFluidValid(dst,sample))continue;}CapabilityTransfer.Port source=new CapabilityTransfer.Port(){public int extract(int n,boolean sim){var actual=f.handler.drain(sized(sample,n),sim?IFluidHandler.FluidAction.SIMULATE:IFluidHandler.FluidAction.EXECUTE);if(!actual.isEmpty()&&!sample.isFluidEqual(actual)){if(!sim)saved.hold(id,"fluid",actual.writeToNBT(new CompoundTag()));throw new IllegalStateException("Fluid identity changed; retained actual in escrow");}return actual.getAmount();}public int receive(int n,boolean sim){return f.handler.fill(sized(sample,n),sim?IFluidHandler.FluidAction.SIMULATE:IFluidHandler.FluidAction.EXECUTE);}};CapabilityTransfer.Port dest=new CapabilityTransfer.Port(){public int extract(int n,boolean sim){return 0;}public int receive(int n,boolean sim){return t.handler.fill(sized(sample,n),sim?IFluidHandler.FluidAction.SIMULATE:IFluidHandler.FluidAction.EXECUTE);}};var predicted=CapabilityTransfer.move(source,dest,amount,true,n->{});if(predicted.simulated()==0)continue;var result=preview?predicted:CapabilityTransfer.move(source,dest,amount,false,n->saved.hold(id,"fluid",sized(sample,n).writeToNBT(new CompoundTag())));var out=receipt(result,f.side,t.side,fluid(sample),preview);out.addProperty("source_identity_tank",tank);out.addProperty("destination_tank_selection","Forge fill chooses tank; to_slot validates compatibility only");return out;}}
        }
        var out=new JsonObject();out.addProperty("status","NO_TRANSFER");out.addProperty("moved",0);out.addProperty("reason","No compatible exposed extract/receive capability, resource, slot or available capacity (auto first 256 slots/tanks)");return out;
    }
    private static CapabilityTransfer.Port energy(IEnergyStorage h){return new CapabilityTransfer.Port(){public int extract(int n,boolean sim){return h.canExtract()?h.extractEnergy(n,sim):0;}public int receive(int n,boolean sim){return h.canReceive()?h.receiveEnergy(n,sim):0;}};}
    private static <T extends Comparable<T>> BlockState set(BlockState s,Property<T> p,String value){return s.setValue(p,p.getValue(value).orElseThrow(()->new IllegalArgumentException("Illegal property value")));}
    private static JsonObject control(MinecraftServer s,UUID id,JsonObject a){var t=target(s,id,a.getAsJsonObject("target"));if(t.player)throw new IllegalArgumentException("Block control only");String name=a.get("property").getAsString();if(!Set.of("powered","enabled").contains(name))throw new IllegalArgumentException("Only actual powered/enabled controls; lit is output, no universal start");var before=t.level.getBlockState(t.pos);var prop=before.getBlock().getStateDefinition().getProperty(name);if(prop==null)throw new IllegalArgumentException("Control property not exposed by this block");var next=set(before,prop,a.get("value").getAsString());boolean preview=a.get("preview").getAsBoolean();var out=new JsonObject();out.addProperty("before",ForgeConstruction.describe(before));out.addProperty("requested",ForgeConstruction.describe(next));if(!preview&&!before.equals(next))t.level.setBlock(t.pos,next,3);out.addProperty("observed",ForgeConstruction.describe(t.level.getBlockState(t.pos)));out.addProperty("status",preview?"SIMULATED":"OBSERVED_SERVER_MAIN");out.addProperty("warning","Block may override property on tick; use lever/button powered state to drive real redstone, inspect live state. No invented start machine API.");return out;}
    public static JsonObject execute(MinecraftServer s,UUID id,String tool,JsonObject a){thread(s);MachineTools.validate(tool,a);if(dev.nanites.core.AssimilationTools.NAMES.contains(tool))return ForgeAssimilation.execute(s,id,tool,a);return switch(tool){case "machine_inspect"->inspect(s,id,a);case "scan_machines"->scan(s,id,a);case "transfer_items","transfer_energy","transfer_fluid"->transfer(s,id,tool,a);case "machine_control"->control(s,id,a);case "machine_recover"->recover(s,id,a);default->throw new IllegalArgumentException("Unknown machine operation");};}
    /** World SavedData survives player death/dimension/logout; never deliver the same escrow twice. */
    public static final class EscrowData extends SavedData {
        private ListTag entries=new ListTag();
        public static EscrowData load(CompoundTag tag){var d=new EscrowData();d.entries=tag.getList("entries",Tag.TAG_COMPOUND);return d;}
        @Override public CompoundTag save(CompoundTag tag){tag.put("entries",entries);return tag;}
        int count(UUID id){int n=0;for(var e:entries)if(((CompoundTag)e).getUUID("owner").equals(id))n++;return n;}
        void hold(UUID id,String type,CompoundTag payload){var entry=new CompoundTag();entry.putUUID("owner",id);entry.putString("type",type);entry.put("payload",payload.copy());entries.add(entry);setDirty();}
        JsonArray summary(UUID id){var a=new JsonArray();int index=0;for(var e:entries){var tag=(CompoundTag)e;if(!tag.getUUID("owner").equals(id))continue;var j=new JsonObject();j.addProperty("index",index++);j.addProperty("type",tag.getString("type"));var payload=tag.getCompound("payload");String type=tag.getString("type");if(type.equals("items"))j.add("resource",item(ItemStack.of(payload)));else if(type.equals("fluid"))j.add("resource",fluid(FluidStack.loadFluidStackFromNBT(payload)));else j.addProperty("amount",payload.getInt("amount"));if(a.size()<16)a.add(j);}return a;}
        CompoundTag entry(UUID id,int index){int i=0;for(var e:entries){var tag=(CompoundTag)e;if(tag.getUUID("owner").equals(id)&&i++==index)return tag;}throw new IllegalArgumentException("Escrow index not found");}
    }
    private static EscrowData escrow(MinecraftServer s){return s.overworld().getDataStorage().computeIfAbsent(EscrowData::load,EscrowData::new,"nanites_machine_escrow");}
    private static JsonObject recover(MinecraftServer s,UUID id,JsonObject a){var t=target(s,id,a.getAsJsonObject("to"));var saved=escrow(s);var entry=saved.entry(id,a.get("index").getAsInt());var payload=entry.getCompound("payload");boolean preview=a.get("preview").getAsBoolean();int slot=a.get("slot").getAsInt(),moved=0,total;String type=entry.getString("type");
        if(type.equals("items")){var sample=ItemStack.of(payload);total=sample.getCount();for(var f:faces(s,id,t,ForgeCapabilities.ITEM_HANDLER)){int possible=insert(f.handler,slot,sample,true);if(possible==0)continue;moved=preview?possible:insert(f.handler,slot,sized(sample,possible),false);if(!preview)entry.put("payload",sized(sample,total-moved).save(new CompoundTag()));break;}}
        else if(type.equals("fluid")){var sample=FluidStack.loadFluidStackFromNBT(payload);total=sample.getAmount();for(var f:faces(s,id,t,ForgeCapabilities.FLUID_HANDLER)){if(slot>=0){slots(f.handler.getTanks(),slot);if(!f.handler.isFluidValid(slot,sample))continue;}int possible=f.handler.fill(sample.copy(),IFluidHandler.FluidAction.SIMULATE);if(possible==0)continue;moved=preview?possible:f.handler.fill(sized(sample,possible),IFluidHandler.FluidAction.EXECUTE);if(!preview)entry.put("payload",sized(sample,total-moved).writeToNBT(new CompoundTag()));break;}}
        else {total=payload.getInt("amount");for(var f:faces(s,id,t,ForgeCapabilities.ENERGY)){if(!f.handler.canReceive())continue;int possible=f.handler.receiveEnergy(total,true);if(possible==0)continue;moved=preview?possible:f.handler.receiveEnergy(possible,false);if(!preview)payload.putInt("amount",total-moved);break;}}
        if(!preview&&moved>0){if(moved==total)saved.entries.remove(entry);saved.setDirty();}var out=new JsonObject();out.addProperty("status",preview?"SIMULATED":"EXECUTED_SERVER_MAIN");out.addProperty("moved",preview?0:moved);out.addProperty("simulated",preview?moved:0);out.addProperty("remaining",preview?total:total-moved);out.add("escrow",saved.summary(id));return out;
    }
}
